find /srv/inventory -type d -exec chmod 750 {} \;
find /srv/inventory -type f -exec chmod 640 {} \;
echo ---
find /srv/inventory -exec ls -lad {} \;

find /srv/inventory -exec ls -lad {} \;
echo ---
find /srv/inventory -type f -exec sha256sum {} \;
echo ---
id inventorysvc; getent group inventory-readers
